function koloAI(){return `<span class="kolo-ai-mark" aria-hidden="true">${logo()}</span>`}
function logo(){return `<svg class="brand-symbol" viewBox="0 0 36 36" aria-hidden="true"><path d="M10 7v22M26 7 12 18l14 11" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function chartRange(){const vals=[project(0),project(7),project(15),project(24),0];return {lo:Math.min(...vals),hi:Math.max(...vals)*1.08};}
function chartY(n){const {lo,hi}=chartRange();return 145-(n-lo)/(hi-lo)*118;}
function forecastChart(mini=false){let pts=[[0,project(0)],[6.9,project(0)],[7,project(7)],[14.9,project(7)],[15,project(15)],[23.9,project(15)],[24,project(24)],[30,project(30)]];let line=pts.map(([d,n],i)=>(i?'L':'M')+(8+d/30*322)+' '+chartY(n)).join(' ');const id=mini?'mini-fill':'forecast-fill';return `<svg class="chart ${mini?'mini-chart':''}" viewBox="0 0 340 166" role="img" aria-label="Projected balance: ${money(project(0))} today, ${money(project(7))} after bills, ${money(project(15))} after income, ${money(project(30))} at month end"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#20b787" stop-opacity=".23"/><stop offset="1" stop-color="#20b787" stop-opacity="0"/></linearGradient></defs>${mini?'':`<path d="M8 45H330M8 95H330M8 145H330" class="chart-grid"/><path d="M8 ${chartY(state.balance)}H330" stroke="#b4c8c0" stroke-dasharray="3 5" fill="none"/>`}<path d="${line}L330 160H8Z" fill="url(#${id})"/><path d="${line}" stroke="#087f5b" stroke-width="2.8" stroke-linejoin="round" fill="none"/>${mini?'':`<circle id="chart-point" cx="${8+state.day/30*322}" cy="${chartY(project(state.day))}" r="5" fill="#087f5b" stroke="white" stroke-width="2"/>`}</svg>`}
'use strict';
const $=s=>document.querySelector(s), money=n=>(n<0?'−':'')+'₦'+Math.round(Math.abs(n)).toLocaleString('en-NG'), escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10h-6v-6H9v6H3Z',chart:'M4 20V12h4v8M10 20V7h4v13M16 20V3h4v17',goal:'M12 3v3M12 18v3M3 12h3M18 12h3M19 5l-5 5M16 12a4 4 0 1 1-4-4M21 12a9 9 0 1 1-9-9',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M18 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM19 3v4M17 5h4',wallet:'M3 6h16v4M3 6v14h18V9H7M16 13h5v4h-5Z',plus:'M12 5v14M5 12h14',back:'m14 6-6 6 6 6',close:'m6 6 12 12M18 6 6 18',check:'m5 12 4 4L19 6',search:'M20 20l-5-5M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',bell:'M18 8a6 6 0 0 0-12 0v6l-2 3h16l-2-3ZM10 21h4',send:'m4 17 13-13M6 4h11v11',down:'M12 4v16M6 14l6 6 6-6',cash:'M3 6h18v12H3ZM12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2ZM8 7h8M8 11h8M8 15h4',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M9 22h6',repeat:'m17 2 4 4-4 4M21 6H7a4 4 0 0 0-4 4m4 12-4-4 4-4M3 18h14a4 4 0 0 0 4-4',brief:'M8 7V4h8v3M3 7h18v14H3ZM3 12h18M10 12v3h4v-3',heart:'M12 21 3 12C-2 4 7 0 12 7 17 0 26 4 21 12Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 3v2M12 19v2M3 12h2M19 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',coffee:'M4 4h12v12a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4ZM16 6h3a3 3 0 0 1 0 6h-3',calendar:'M4 5h16v16H4ZM4 10h16M8 3v4M16 3v4',arrow:'M5 12h14m-5-5 5 5-5 5'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`}function round(n,action,label){return `<button class="round" ${action?`data-action="${action}"`:''} aria-label="${label||action||n}">${icon(n)}</button>`}
let state={page:'intro',step:0,balance:420000,mode:'personal',day:0,family:18500,chat:[],rules:[true,true,false,true],cash:0,receipts:[],paidBills:[],household:40000,pots:[{name:'Emergency',icon:'◈',amount:60000,target:300000},{name:'Travel',icon:'✈',amount:20000,target:600000},{name:'Business',icon:'▣',amount:10000,target:200000}],transactions:[{name:'Creative studio',sub:'Client payment · Today',amount:240000,icon:'brief'},{name:'Mama',sub:'Family support · Yesterday',amount:-18500,icon:'heart'},{name:'Dining & takeaway',sub:'Food · 3 Oct',amount:-18000,icon:'coffee'}],circles:[{name:'Lagos Creatives',amount:30000,members:6,received:5,paid:false,messages:[]}],subs:[{name:'Netflix',amount:7000,on:true},{name:'Canva',amount:12000,on:true},{name:'Google One',amount:4000,on:true},{name:'Music & other',amount:12000,on:true}]};
try{const saved=JSON.parse(sessionStorage.getItem('koloflow-payment-session')||'null');if(saved&&saved.version===1)state={...state,...saved.state};}catch{}
const reserve=()=>(state.paidBills.includes('rent')?0:180000)+(state.paidBills.includes('recurring')?0:state.subs.filter(s=>s.on).reduce((a,s)=>a+s.amount,0))+state.family+state.pots.reduce((a,p)=>a+p.amount,0),safe=()=>Math.max(0,state.balance-reserve()),project=d=>state.balance+(d>=15?240000:0)-(d>=7&&!state.paidBills.includes('recurring')?state.subs.filter(s=>s.on).reduce((a,s)=>a+s.amount,0):0)-(d>=24&&!state.paidBills.includes('rent')?180000:0);
const pages=[['today','home','Today'],['future','chart','Future'],['goals','goal','Goals'],['circles','users','Circles'],['copilot','spark','Kolo AI']];
function focusPage(){const target=$('main h1')||$('main');if(target){target.tabIndex=-1;target.focus({preventScroll:true})}}
// Motion keeps balances readable immediately; only surfaces move.
const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
const activeMotion=new Set();
let motionView='',motionChatCount=0;
const motionAllowed=()=>!motionPreference.matches&&document.documentElement.dataset.input!=='keyboard';
function animateSurface(element,frames,options={}){if(!element||!motionAllowed()||!element.animate)return;const animation=element.animate(frames,{duration:220,easing:'cubic-bezier(0.23,1,0.32,1)',...options});activeMotion.add(animation);const release=()=>activeMotion.delete(animation);animation.onfinish=release;animation.oncancel=release;}
function stopMotion(){activeMotion.forEach(a=>a.cancel());activeMotion.clear();}
function pageMotion(){stopMotion();const key=state.page+':'+(state.page==='intro'?state.step:state.mode);const main=$('main');if(key!==motionView){motionView=key;if(state.page==='intro'){animateSurface($('.welcome-caption')||$('.video-introduction'),[{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:280});animateSurface($('.intro-visual .glass-preview')||$('.intro-pots'),[{opacity:0,transform:'translateY(16px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:280});}else{animateSurface(main?.querySelector('.page-intro,.copilot-title'),[{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:180});const surfaces=main?.querySelectorAll(':scope > .hero,:scope > .forecast-card,:scope > .wallet-summary,:scope > .copilot-stage,:scope > .grid2,:scope > .stack,:scope > .section,:scope > .copilot-invite');surfaces?.forEach((el,i)=>animateSurface(el,[{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{delay:Math.min(i*16,48)}));main?.querySelectorAll('.progress span,.reserve-line span').forEach(el=>animateSurface(el,[{transform:'scaleX(.15)'},{transform:'scaleX(1)'}],{duration:260}));const card=main?.querySelector('.spending-card');if(card&&motionAllowed())card.classList.add('motion-card');}}if(state.page==='copilot'&&state.chat.length>motionChatCount){animateSurface(main?.querySelector('.chat-item:last-child'),[{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:180});}motionChatCount=state.chat.length;}
document.addEventListener('pointerdown',()=>document.documentElement.dataset.input='pointer',{passive:true});
document.addEventListener('keydown',()=>{document.documentElement.dataset.input='keyboard';stopMotion();},{capture:true});
motionPreference.addEventListener('change',e=>{if(e.matches){stopMotion();const video=$('.video-welcome video');if(video){video.autoplay=false;video.pause();}}else{const video=$('.video-welcome video');if(video){video.autoplay=true;video.play().catch(()=>{});}}});
function navigate(p){state.page=p;render();window.scrollTo(0,0);focusPage()}
function nav(){return `<nav class="nav" aria-label="Main navigation">${pages.map(([p,i,n])=>`<button data-page="${p}" class="${state.page===p?'active':''}" ${state.page===p?'aria-current="page"':''}><span class="nav-icon">${p==='copilot'?koloAI():icon(i)}</span>${n}</button>`).join('')}</nav>`}
function sidebar(){return `<aside class="sidebar"><div class="brand">${logo()}<span>KoloFlow<span class="brand-caption">PERSONAL MONEY OS</span></span></div><span class="eyebrow sidebar-label">YOUR WORKSPACE</span><nav aria-label="Desktop navigation">${[...pages,['wallet','wallet','Wallet']].map(([p,i,n])=>`<button data-page="${p}" class="${state.page===p?'active':''}" ${state.page===p?'aria-current="page"':''}>${p==='copilot'?koloAI():icon(i)}${n}</button>`).join('')}</nav><div class="sidebar-tools"><button data-action="tools">${icon('settings')}Money tools</button><button data-action="onboarding">${icon('spark')}Welcome</button></div><div class="sidebar-footer"><div class="user-row"><span class="profile">JE</span><div><strong>Josh Ehiz</strong><p>Personal workspace</p></div></div><div class="demo-footer"><span>Portfolio demo</span><button data-action="reset" aria-label="Reset demo">${icon('repeat')}</button></div></div></aside>`}
function panel(){return `<aside class="desktop-panel"><button class="assistant-panel" data-page="copilot"><img src="assets/flow-sculpture.webp" alt=""><span class="eyebrow">YOUR MONEY ASSISTANT</span><h2>A clearer head.<br>A better next move.</h2><p>Ask Kolo what your money can do.</p><span class="assistant-cta">Start a conversation ${koloAI()}</span></button><section class="panel-section"><div class="section-head"><h3>Financial pulse</h3><span class="badge">Stable</span></div><div class="health"><span class="health-score">78<span>/ 100</span></span><p class="muted">${state.paidBills.includes('rent')?'Rent is paid.':'Rent is protected.'}<br>Dining needs a little attention.</p></div><button class="text-button" data-action="health">View your money health</button></section><section class="panel-section"><span class="eyebrow">COMING UP</span><h3 style="margin-top:16px">Recurring payments</h3><p class="muted">${state.paidBills.includes('recurring')?'Paid in demo':'In 7 days'}</p><div class="small-amount">${money(state.subs.filter(s=>s.on).reduce((a,s)=>a+s.amount,0))}</div><button class="text-button" data-action="subscriptions">Review subscriptions</button></section><p class="disclosure">Sample finances. No real accounts or payments are connected.</p></aside>`}
function top(name='KoloFlow'){return `<header class="topbar"><div class="brand mobile-brand">${logo()}${name}</div><div class="desktop-context"><span class="eyebrow">PERSONAL WORKSPACE</span></div><div class="header-actions">${round('wallet','wallet','Open wallet')}${round('bell','alerts','Notifications')}<span class="profile">JE</span></div></header>`}
function header(t,action='tools'){return `<header class="page-header">${round('back','today','Back to Today')}<h2>${t}</h2>${round('plus',action,'Open '+t+' options')}</header>`}
function tx(t){return `<div class="transaction"><span class="transaction-icon">${icon(t.icon)}</span><div class="details"><h3>${escape(t.name)}</h3><p class="muted">${escape(t.sub)}</p>${t.receipt?`<button class="text-button receipt-link" data-receipt="${t.receipt}">View receipt</button>`:''}</div><strong class="${t.amount>0?'income':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}</strong></div>`}
function introVisual(step){
if(step===0)return `<div class="intro-spend glass-preview"><span class="preview-icon">${icon('shield')}</span><span class="eyebrow">SAFE TO SPEND</span><strong>₦96,500<span>.00</span></strong><div class="intro-meter"><i></i></div><div class="intro-protected">${icon('check')} Rent protected</div></div>`;
if(step===1)return `<div class="intro-forecast glass-preview"><span class="eyebrow">YOUR NEXT 30 DAYS</span><strong>₦445,000</strong>${forecastChart(true)}<div class="preview-dates"><span>Today</span><span>Income</span><span>Rent</span></div><span class="intro-protected">${icon('chart')} See it before it happens</span></div>`;
if(step===2)return `<div class="intro-pots"><div class="glass-preview"><span class="preview-icon">${icon('goal')}</span><span>Travel</span><strong>₦20,000</strong><div class="intro-meter"><i style="width:30%"></i></div></div><div class="glass-preview"><span class="preview-icon">${icon('users')}</span><span>Lagos Creatives</span><strong>6 people.<br>One shared goal.</strong><div class="preview-people"><i>JE</i><i>AM</i><i>CH</i><i>+3</i></div></div></div>`;
return `<div class="intro-chat glass-preview"><span class="preview-icon">${koloAI()}</span><span class="eyebrow">KOLO AI</span><div class="preview-question">What can I spend this weekend?</div><p>You have <strong>₦96,500</strong> of spending room.</p><div class="intro-protected">${icon('shield')} Your commitments come first.</div></div>`;
}
function intro(){const step=state.step;if(step===0)return `<main class="video-welcome"><video autoplay muted loop playsinline preload="auto" poster="assets/flow-sculpture.webp" aria-label="Animated KoloFlow glass K welcome"><source src="assets/welcome-k.mp4" type="video/mp4"></video><header class="video-brand">${logo()}<span>KoloFlow</span></header><div class="video-introduction"><span class="eyebrow">YOUR MONEY. IN FLOW.</span><h1>Make room for<br><span>what’s next.</span></h1><p>Know what you can spend.<br>Protect what matters.</p><button class="primary video-next" data-action="intro-next">Next <span class="step-count">01 / 04</span></button></div></main>`;const slides=[['Spend with<br><span>confidence.</span>','Know what’s free to use. Protect what matters.'],['See your money’s<br><span>next move.</span>','Preview bills, payday and the days between.'],['Big dreams.<br><span>Shared progress.</span>','Build money pots. Grow with your circle.'],['A little clarity.<br><span>On demand.</span>','Ask Kolo. Explore your options before you act.']];return `<main class="phone onboarding onboarding-four step-${step}"><header class="topbar"><div class="brand">${logo()}KoloFlow</div><button class="intro-demo" data-page="today">Skip</button></header><div class="welcome-stage"><div class="intro-visual" aria-label="${['Safe-to-spend preview','Future balance preview','Savings and circles preview','Copilot preview'][step]}"><img class="intro-sculpture" src="assets/flow-sculpture.webp" alt="Emerald refractive glass KoloFlow sculpture">${introVisual(step)}</div><div class="welcome-caption"><span class="eyebrow">${['SPENDING ROOM','FUTURE BALANCE','GOALS & CIRCLES','YOUR MONEY ASSISTANT'][step]}</span><h1>${slides[step][0]}</h1><p>${slides[step][1]}</p><div class="intro-pagination" aria-label="Welcome page ${step+1} of 4">${slides.map((_,i)=>`<span class="${step===i?'current':''}"></span>`).join('')}</div><button class="primary welcome-button" data-action="intro-next">Next <span class="step-count">0${step+1} / 04</span></button><div class="intro-bottom">${step>0?'<button data-action="intro-back">Back</button>':'<span>Explore with sample finances</span>'}<span>${step===3?'Your workspace is next':'A clearer relationship with money'}</span></div></div></div></main>`}

function today(){const hustle=state.mode==='business',days=Math.floor(safe()/4200);return `<main class="phone home">${top()}<div class="page-intro"><div><p class="eyebrow">YOUR MONEY, TODAY</p><h1>Good morning, Josh<span class="greeting-dot">.</span></h1></div><div class="mode" aria-label="Money workspace"><button class="${!hustle?'active':''}" data-mode="personal">Personal</button><button class="${hustle?'active':''}" data-mode="business">Hustle</button></div></div><section class="hero"><div class="hero-top"><span class="hero-label">${hustle?'YOUR BUSINESS':'YOUR SPENDING ROOM'}</span><span class="hero-badge">${icon('shield')}${hustle?'Profit, in focus':days+' days covered'}</span></div><p class="hero-description">${hustle?'Profit this month':'Actually safe to spend'}</p><div class="amount">${money(hustle?185000:safe())}<span class="amount-decimal">.00</span></div><p class="hero-helper">${hustle?'Revenue ₦365,000 · Expenses ₦180,000':'After protecting the things that matter.'}</p><div class="hero-footer"><span>${hustle?'Unpaid invoices':'Available balance'}<strong>${money(hustle?120000:state.balance)}</strong></span><button data-action="${hustle?'history':'bills'}">${hustle?'View activity':'View commitments'}${icon('receipt')}</button></div><div class="reserve-line" aria-hidden="true"><span style="width:${Math.max(2,Math.min(100,safe()/state.balance*100))}%"></span></div><div class="reserve-legend"><span><i></i>Free to use</span><span><i class="reserved"></i>Protected ${money(reserve())}</span></div></section><button class="copilot-invite" data-page="copilot"><img src="assets/flow-sculpture.webp" alt=""><span><span class="eyebrow">KOLO AI</span><strong>What’s your next money move?</strong><span class="muted">Let’s think it through together.</span></span><span class="invite-icon">${koloAI()}</span></button><section class="section"><div class="section-head"><h2>Your essentials</h2><button class="text-button" data-action="bills">View all</button></div><div class="essentials"><div><span class="essential-icon">${icon('home')}</span><span>Rent<strong>${money(180000)}</strong></span><span class="check-status">${icon('check')}${state.paidBills.includes('rent')?'Paid':'Covered'}</span></div><div><span class="essential-icon">${icon('goal')}</span><span>Savings<strong>${money(state.pots.reduce((a,p)=>a+p.amount,0))}</strong></span><span class="check-status">${icon('check')}On track</span></div></div><button class="budget-note" data-action="invisible">${icon('coffee')}Dining is ₦18,000 above budget<span>Review</span></button></section><section class="section"><div class="section-head"><h2>Make a move</h2><button class="text-button" data-action="tools">Money tools</button></div><div class="shortcuts">${[['send','transfer','Send money'],['cash','cash','Log cash'],['chart','simulator','What if?'],['repeat','autopilot','Autopilot']].map(([i,a,l])=>`<button class="shortcut" data-action="${a}"><span>${icon(i)}</span>${l}</button>`).join('')}</div></section><section class="section"><div class="section-head"><div><h2>Ahead of you</h2><p class="muted">Expected balance in 30 days</p></div><button class="text-button" data-page="future">Explore future</button></div><div class="mini-forecast"><strong>${money(project(30))}</strong>${forecastChart(true)}<div class="forecast-labels"><span>Today</span><span>Income</span><span>Rent</span><span>30 days</span></div></div></section><section class="section activity"><div class="section-head"><h2>Recent activity</h2><button class="text-button" data-action="history">See all</button></div>${state.transactions.slice(0,3).map(tx).join('')}</section><p class="demo-label">Sample finances · All actions are simulated</p></main>`}
function future(){return `<main class="phone future">${top()}<div class="page-intro"><div><p class="eyebrow">LOOKING AHEAD</p><h1>A little foresight.<br>A lot more freedom.</h1></div></div><section class="forecast-card"><div class="section-head"><span class="eyebrow">PROJECTED BALANCE</span><span class="badge">Next 30 days</span></div><div class="amount" id="forecast-amount">${money(project(state.day))}</div><p class="muted">Expected income and known commitments.</p><div class="chart-section">${forecastChart()}<div class="forecast-labels"><span>Today</span><span>Bills</span><span>Income</span><span>Rent</span><span>Month end</span></div></div><div class="forecast-scrub"><label for="future-day">Move through your month</label><span id="day-label">Day ${state.day}</span></div><input id="future-day" class="slider" type="range" min="0" max="30" value="${state.day}" aria-label="Future day"></section><section class="section"><div class="section-head"><h2>Your money timeline</h2><button class="text-button" data-action="bills">Commitments</button></div><div class="timeline">${[[state.paidBills.includes('recurring')?'Paid':'In 7 days',state.paidBills.includes('recurring')?'Recurring payments · Paid':'Recurring payments',state.paidBills.includes('recurring')?0:-state.subs.filter(s=>s.on).reduce((a,s)=>a+s.amount,0),'repeat'],['In 15 days','Expected client income',240000,'brief'],[state.paidBills.includes('rent')?'Paid':'In 24 days',state.paidBills.includes('rent')?'Rent payment · Paid':'Rent payment',state.paidBills.includes('rent')?0:-180000,'home']].map(([date,t,n,i])=>`<div class="timeline-row"><span class="timeline-icon">${icon(i)}</span><div><span class="eyebrow">${date}</span><h3>${t}</h3></div><strong class="${n>0?'income':''}">${n===0?'Settled':(n>0?'+':'−')+money(Math.abs(n))}</strong></div>`).join('')}</div></section><button class="scenario-card section" data-action="simulator"><span class="scenario-icon">${icon('chart')}</span><span><span class="eyebrow">WHAT IF?</span><h2>Test a move before you make it.</h2><p>New laptop? Higher rent? A quieter month?</p></span><span class="scenario-open">Open simulator</span></button><p class="disclosure">An illustration using sample data. Expected income is not guaranteed.</p></main>`}
function goals(){return `<main class="phone">${top()}<div class="page-intro"><div><p class="eyebrow">MONEY WITH PURPOSE</p><h1>Make space for<br>the life you want.</h1></div>${round('plus','new-pot','Create a money pot')}</div><section class="savings-summary"><span class="eyebrow">PROTECTED IN YOUR POTS</span><div class="amount">${money(state.pots.reduce((a,p)=>a+p.amount,0))}</div><div class="summary-bottom"><span>${state.pots.length} plans in motion</span><button data-action="allocate">${icon('spark')}Get allocation help</button></div></section><section class="section"><div class="section-head"><h2>Your money pots</h2><button class="text-button" data-action="new-pot">New pot</button></div><div class="grid2 pot-grid">${state.pots.map((p,i)=>`<article class="card pot-card"><div class="pot-top"><span class="pot-icon">${icon(p.name==='Emergency'?'shield':p.name==='Business'?'brief':'goal')}</span><button class="pot-add" data-pot="${i}" aria-label="Add money to ${escape(p.name)}">${icon('plus')}</button></div><h3>${escape(p.name)}</h3><div class="small-amount">${money(p.amount)}</div><p class="muted">of ${money(p.target)}</p><div class="progress" role="progressbar" aria-label="${escape(p.name)} progress" aria-valuenow="${Math.min(100,Math.round(p.amount/p.target*100))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(100,p.amount/p.target*100)}%"></span></div><span class="pot-percent">${Math.round(p.amount/p.target*100)}% there</span></article>`).join('')}<button class="new-pot-card" data-action="new-pot"><span class="pot-icon">${icon('plus')}</span><h3>Room for another dream.</h3><p class="muted">Create a money pot</p></button></div></section><button class="scenario-card section" data-action="life"><span class="scenario-icon">${icon('goal')}</span><span><span class="eyebrow">LIFE GOALS</span><h2>Turn “one day” into a plan.</h2><p>Move house. Start a business. See the world.</p></span></button><section class="section"><button class="tool full-tool" data-action="smoothing">${icon('repeat')}<span><h3>Make your own payday</h3><p class="muted">Give irregular income a steady rhythm.</p></span></button></section></main>`}
function circles(){return `<main class="phone">${top()}<div class="page-intro"><div><p class="eyebrow">AJO / ESUSU</p><h1>Your people.<br>Your shared progress.</h1></div>${round('plus','new-circle','Create a circle')}</div><div class="stack">${state.circles.map((c,i)=>`<article class="circle-card"><div class="section-head"><span class="circle-label">${icon('users')}SAVINGS CIRCLE</span><span class="badge">Active</span></div><h2>${escape(c.name)}</h2><p class="muted">${c.members} members · One monthly contribution</p><div class="circle-members"><div class="avatars">${['JE','AM','CH','TO','KE','EM'].slice(0,c.members).map((a,j)=>`<span class="avatar avatar-${j}">${a}</span>`).join('')}</div><span class="muted">Growing together</span></div><div class="circle-amounts"><div><p class="muted">Your monthly share</p><div class="small-amount">${money(c.amount)}</div></div><div><p class="muted">Circle payout</p><div class="small-amount">${money(c.amount*c.members)}</div></div></div><div class="circle-progress"><span>${(c.received??c.members-1)+(c.paid?1:0)} of ${c.members} contributions received</span><div class="progress"><span style="width:${((c.received??c.members-1)+(c.paid?1:0))/c.members*100}%"></span></div></div><div class="circle-deadline">${icon('calendar')}Due 10 October<span>${c.paid?'Your share is in':'Your share is pending'}</span></div><button class="primary ${c.paid?'secondary':''}" data-circle-pay="${i}" ${c.paid?'disabled':''}>${c.paid?'Contribution recorded':'Contribute '+money(c.amount)}</button><button class="text-button circle-ledger" data-circle-detail="${i}">Ledger, payout order & group chat</button></article>`).join('')}</div><section class="section"><div class="trust-strip">${icon('shield')}<span>Transparent ledger.<br><strong>Every contribution, accounted for.</strong></span></div><button class="tool full-tool" data-action="family-space">${icon('heart')}<span><h3>Your family money space</h3><p class="muted">Share a goal. Keep your own privacy.</p></span></button></section><p class="disclosure">A portfolio demonstration. Contributions and group messages are simulated.</p></main>`}
function copilot(){return `<main class="phone copilot">${top()}<div class="copilot-title"><span class="kolo-ai-wordmark">${koloAI()}<span>Kolo <b>AI</b></span></span><span class="badge">Demo assistant</span></div>${state.chat.length?'<h1 class="sr-only">Kolo AI conversation</h1>':`<div class="copilot-stage"><img src="assets/flow-sculpture.webp" alt="Original KoloFlow emerald sculpture"><div class="copilot-stage-copy"><h1>Let’s make<br>your next move<br><span>make sense.</span></h1><p>Your finances. A little perspective.</p></div></div><div class="prompt-label">A FEW PLACES TO START</div><div class="grid2 prompts">${[['shield','Can I afford ₦180k rent?'],['chart','Why am I broke by the 20th?'],['cash','What can I spend this weekend?'],['goal','Help me save ₦600k']].map(([i,t])=>`<button class="prompt" data-prompt="${t}">${icon(i)}<span>${t}</span></button>`).join('')}</div>`}<div class="messages" aria-live="polite">${state.chat.map(m=>`<div class="chat-item ${m.role}"><span class="chat-author">${m.role==='user'?'You':koloAI()+'Kolo AI'}</span><div class="message">${escape(m.text)}</div></div>`).join('')}</div><form id="chat-form" class="compose"><input id="chat-input" aria-label="Ask about your money" placeholder="What’s on your mind?" required maxlength="400"><button type="button" class="round voice-button" data-action="voice" aria-label="Voice assistant">${icon('mic')}</button><button class="round send-button" aria-label="Send question">${icon('send')}</button></form><p class="demo-label">Answers use sample finances. No money moves through chat.</p></main>`}
function wallet(){return `<main class="phone">${top()}<div class="page-intro"><div><p class="eyebrow">YOUR WALLET</p><h1>One place.<br>A clearer picture.</h1></div>${round('plus','receive','Add sample income')}</div><section class="wallet-summary"><span class="eyebrow">TOTAL AVAILABLE BALANCE</span><div class="amount">${money(state.balance)}</div><div class="wallet-actions"><button class="primary" data-action="receive">${icon('down')}Receive</button><button class="primary secondary" data-action="transfer">${icon('send')}Send money</button></div></section><div class="wallet-receipts"><button class="text-button" data-action="receipts">${icon('receipt')}Payment receipts</button><button class="text-button" data-action="card-pay">${icon('wallet')}Card payment</button></div><section class="section"><div class="section-head"><h2>Your spending card</h2><span class="badge">Demo card</span></div><div class="spending-card"><div class="section-head"><div class="brand">${logo()}KoloFlow</div><span class="card-label">${state.frozen?'FROZEN':'PERSONAL'}</span></div><div class="card-details"><span>SPENDING ROOM</span><strong>${money(safe())}</strong></div><div class="card-footer"><span>JOSH EHIZ<span>•••• 4327</span></span><span class="card-contactless">${icon('wallet')}</span></div></div><div class="card-controls">${[['shield','card-block',state.frozen?'Unfreeze card':'Freeze card'],['eye','card-details','Card details'],['calendar','bills','View bills']].map(([i,a,t])=>`<button data-action="${a}">${icon(i)}${t}</button>`).join('')}</div></section><section class="section"><div class="section-head"><h2>Connected views</h2><button class="text-button" data-action="accounts">Details</button></div><div class="account-row"><span class="account-icon">₦</span><span><h3>Naira account</h3><p class="muted">Sample account</p></span><strong>${money(state.balance)}</strong></div><div class="account-row"><span class="account-icon">$</span><span><h3>Dollar account</h3><p class="muted">Sample account</p></span><strong>$0.00</strong></div></section><button class="tool full-tool section" data-action="invest">${icon('chart')}<span><h3>Plan your investments</h3><p class="muted">See how regular contributions add up.</p></span></button><p class="disclosure">No financial accounts or card networks are connected.</p></main>`}
function persistState(){try{sessionStorage.setItem('koloflow-payment-session',JSON.stringify({version:1,state}));}catch{}}
function render(){persistState();const p=state.page;$('#app').innerHTML=`<div class="layout ${p==='intro'?'intro-layout':''}">${sidebar()}${(p==='intro'?intro():({today,future,goals,circles,copilot,wallet}[p]||today)()).replace('<main','<main id="main-content" tabindex="-1"')}${p==='intro'?'':nav()+panel()}</div>`;bind();const video=$('.video-welcome video');if(video&&window.matchMedia('(prefers-reduced-motion: reduce)').matches){video.autoplay=false;video.pause();}pageMotion();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
let modalTrigger;
function modal(title,html){if(!$('#modal').open)modalTrigger=document.activeElement;$('#modal-content').innerHTML=`<div class="modal-top"><h2 id="dialog-title">${escape(title)}</h2>${round('close','close','Close dialog')}</div>${html}`;$('#modal').showModal();bind($('#modal'));$('#modal-content').querySelector('button')?.focus();animateSurface($('#modal-content'),[{opacity:0,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:180});}
function close(){if($('#modal').open){$('#modal').close();if(modalTrigger?.isConnected&&modalTrigger!==document.body)modalTrigger.focus();else focusPage();}}
function form(title,fields,onSubmit,button='Save in demo'){modal(title,`<form id="action-form" class="form">${fields}<button class="primary">${button}</button><p class="disclosure">Changes apply to this demo session only.</p></form>`);$('#action-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));onSubmit(d);};}
const field=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${escape(value)}" required ${extra}></label>`;
function record(name,n,ico='cash'){state.balance+=n;state.transactions.unshift({name,sub:'Just now · Demo',amount:n,icon:ico});}

function transferForm(values={}){form('Send money',field('recipient','Recipient',values.recipient||'')+field('bank','Bank or wallet',values.bank||'')+field('account','Account number',values.account||'','text','inputmode="numeric" pattern="[0-9]{10}" maxlength="10" placeholder="10 digits"')+field('amount','Amount (₦)',values.amount||'','number','min="1" max="10000000"')+field('note','Payment note',values.note||'Transfer'),d=>reviewPayment({recipient:d.recipient,amount:Number(d.amount),kind:'Transfer',method:'Naira account',bank:d.bank,account:d.account,note:d.note},()=>transferForm(d)),'Review transfer');}
function cardPaymentForm(values={}){form('Card payment',field('recipient','Merchant',values.recipient||'')+field('amount','Amount (₦)',values.amount||'','number','min="1" max="10000000"')+`<div class="payment-method">${icon('wallet')}KoloFlow card · •••• 4327<span>${state.frozen?'Frozen':'Active'}</span></div>`,d=>reviewPayment({recipient:d.recipient,amount:Number(d.amount),kind:'Card payment',method:'KoloFlow card · •••• 4327',card:true},()=>cardPaymentForm(d)),'Review card payment');}
function paymentRows(r){return `<dl class="payment-details"><div><dt>${r.incoming?'From':'To'}</dt><dd>${escape(r.recipient)}</dd></div>${r.bank?`<div><dt>Destination</dt><dd>${escape(r.bank)} · •••• ${escape(r.account.slice(-4))}</dd></div>`:''}<div><dt>Payment type</dt><dd>${escape(r.kind)}</dd></div><div><dt>${r.incoming?'Received into':'Paid from'}</dt><dd>${escape(r.method)}</dd></div><div><dt>Fee</dt><dd>₦0</dd></div>${r.note?`<div><dt>Note</dt><dd>${escape(r.note)}</dd></div>`:''}</dl>`;}
function reviewPayment(p,onEdit){if(!Number.isFinite(p.amount)||p.amount<=0)return toast('Enter a valid amount.');const blocked=p.card&&state.frozen,room=p.release?Math.max(0,Math.min(state.balance,state.balance-reserve()+p.release)):safe(),enough=p.amount<=room;modal(p.card?'Confirm card payment':'Review payment',`<div class="payment-review"><span class="payment-emblem">${icon(p.card?'wallet':'send')}</span><p class="eyebrow">${escape(p.kind)}</p><div class="payment-amount">${money(p.amount)}</div><p class="muted">To ${escape(p.recipient)}</p></div>${paymentRows(p)}<div class="payment-total"><span>Total to pay</span><strong>${money(p.amount)}</strong></div><p class="payment-notice ${blocked||!enough?'payment-error':''}">${blocked?'Your card is frozen. Unfreeze it in Wallet before paying.':!enough?'This exceeds the money available for this payment. Edit the amount or add income.':`Spending room after payment: ${money(Math.max(0,safe()-p.amount+(p.release||0)))}`}</p><button class="primary payment-confirm" id="confirm-payment" ${blocked||!enough?'disabled':''}>Confirm ${money(p.amount)} · Demo</button><button class="primary secondary section" id="edit-payment">${onEdit?'Edit payment':'Go back'}</button><p class="disclosure">Demo payment only. No real money will move.</p>`);$('#edit-payment').onclick=()=>{close();onEdit?.()};let committed=false;$('#confirm-payment').onclick=()=>{if(committed)return;committed=true;if(p.card&&state.frozen)return toast('Your card is frozen.');completePayment(p)};}
function completePayment(p){if(!p.incoming&&p.amount>(p.release?Math.max(0,Math.min(state.balance,state.balance-reserve()+p.release)):safe()))return toast('The available amount has changed. Review this payment again.');p.apply?.();const r={id:'KF-'+crypto.randomUUID().replaceAll('-','').slice(0,12).toUpperCase(),recipient:p.recipient,amount:p.amount,kind:p.kind,method:p.method,bank:p.bank,account:p.account,note:p.note,incoming:!!p.incoming,date:new Date().toISOString(),status:'Completed'};record(p.recipient,p.incoming?p.amount:-p.amount,p.incoming?'down':p.card?'wallet':'send');state.transactions[0].receipt=r.id;state.receipts.unshift(r);close();render();showReceipt(r,true);}
function showReceipt(r,fresh=false){if(!r)return toast('Receipt unavailable.');close();const date=new Date(r.date).toLocaleString('en-NG',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Lagos'});modal(fresh?(r.incoming?'Money received':'Payment complete'):'Payment receipt',`<article class="receipt-sheet"><div class="receipt-brand">${logo()}KoloFlow<span>DEMO RECEIPT</span></div><div class="receipt-success ${fresh?'fresh-success':''}">${icon('check')}</div><p class="receipt-status" role="status">${r.status} in demo</p><div class="payment-amount">${money(r.amount)}</div><p class="muted receipt-description">${r.incoming?'Received from':'Paid to'} ${escape(r.recipient)}</p>${paymentRows(r)}<dl class="payment-details receipt-meta"><div><dt>Date & time</dt><dd>${escape(date)} WAT</dd></div><div><dt>Reference</dt><dd>${r.id}</dd></div><div><dt>Status</dt><dd>Completed · Simulated</dd></div></dl><p class="disclosure">Portfolio demonstration. This receipt is not proof of a real bank transaction.</p></article><div class="receipt-actions"><button class="primary" id="download-payment-receipt">${icon('receipt')}Download receipt</button><button class="primary secondary" data-action="close">Done</button></div>`);$('#download-payment-receipt').onclick=()=>downloadReceipt(r,date);if(fresh){animateSurface($('.receipt-success'),[{opacity:.4,transform:'scale(.9)'},{opacity:1,transform:'scale(1)'}],{duration:280});animateSurface($('.receipt-success .icon'),[{opacity:0,transform:'translateY(3px)'},{opacity:1,transform:'translateY(0)'}],{duration:180,delay:60});}}
function receiptHistory(){modal('Payment receipts',state.receipts.length?`<p class="muted">Completed payments in this demo session.</p><div class="stack section">${state.receipts.map(r=>`<button class="receipt-history-row" data-receipt="${r.id}"><span class="transaction-icon">${icon('receipt')}</span><span><strong>${escape(r.recipient)}</strong><span>${escape(r.kind)} · ${new Date(r.date).toLocaleDateString('en-NG')}</span></span><b>${money(r.amount)}</b></button>`).join('')}</div>`:`<div class="receipt-empty">${icon('receipt')}<h3>Your receipts will live here.</h3><p class="muted">Complete a transfer, card payment, bill or contribution to create your first receipt.</p><button class="primary section" data-action="transfer">Send money</button></div>`);}
function downloadReceipt(r,date){const html=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KoloFlow demo receipt ${r.id}</title><style>body{font:16px system-ui;color:#15392e;background:#e9f7f1;padding:24px}article{max-width:520px;margin:auto;background:white;border:1px solid #cbe3d8;border-radius:24px;padding:32px}h1{font-size:24px}h2{font-size:38px}dl>div{display:flex;justify-content:space-between;gap:24px;padding:14px 0;border-bottom:1px solid #dde9e3}dt{color:#526c62}dd{margin:0;text-align:right;overflow-wrap:anywhere}small{display:block;line-height:1.6;margin-top:24px;color:#526c62}.brand-symbol{width:32px;height:32px}@media print{body{background:white;padding:0}article{border:0}}</style><article><h1>KoloFlow · Demo receipt</h1><p>Completed · Simulated</p><h2>${money(r.amount)}</h2>${paymentRows(r)}<dl><div><dt>Date & time</dt><dd>${escape(date)} WAT</dd></div><div><dt>Reference</dt><dd>${r.id}</dd></div></dl><small>Portfolio demonstration. No real money moved. This receipt is not proof of a bank transaction.<br>Use your browser’s Print option to save as PDF.</small></article></html>`;const u=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='KoloFlow-demo-receipt-'+r.id+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);toast('Receipt downloaded. Open it to print or save as PDF.');}

function ask(q){state.chat.push({role:'user',text:q});let t='',l=q.toLowerCase();if(/rent|afford/.test(l)){t=`${state.paidBills.includes('rent')?'Your ₦180,000 rent is already paid.':'Your ₦180,000 rent is already reserved.'}\n\nAvailable balance: ${money(state.balance)}\nAll commitments: ${money(reserve())}\nSafe to spend: ${money(safe())}\n\n${state.paidBills.includes('rent')?'Rent is settled in this session.':'Your current plan covers rent.'} Expected income is still a projection.`;}else if(/600|save|december/.test(l)){t='To build ₦600,000 by 31 December from today, you have about three monthly contributions. Start with ₦200,000 a month.\n\nThat exceeds your current safe-to-spend amount. A longer timeline or smaller target would give you more breathing room. Open Goals to make a plan.';}else if(/broke|20th|delivery|small|invisible/.test(l)){t='Your sample spending shows ₦71,400 in delivery fees and ₦94,000 in small transfers this month. These category totals may overlap.\n\nDining is ₦18,000 over budget. Try a weekly cap and protect bills when income arrives. The invisible-spending report has the breakdown.';}else if(/mama|family|30k/.test(l)){t=`Your family-support reserve is ${money(state.family)} of a ₦50,000 monthly budget.\n\nUse Family support in Money tools to set aside a new amount. I won’t move money from a chat message.`;}else if(/landlord|chisom|last year|phone|search/.test(l)){t='Money memory found these sample records:\n\nLandlord · ₦180,000 · 29 September\nChisom · ₦15,000 · 21 September\nPhone purchase · ₦145,000 · 12 August\n\nOpen Money memory to filter these records.';}else if(/week|spend|weekend/.test(l)){t=`You have ${money(safe())} safe to spend after protecting your commitments.\n\nA sample weekend cap of ${money(Math.min(15000,safe()))} keeps a buffer for the rest of the month. Your account balance alone overstates what is freely available.`;}else{t=`Based on this demo, your available balance is ${money(state.balance)} and ${money(safe())} is safe to spend.\n\nI can show your rent coverage, weekend spending room, family reserve, savings plan or spending patterns. Ask about one of those to explore further.`;}state.chat.push({role:'assistant',text:t});navigate('copilot');}
const toolsList=[['simulator','chart','What-if simulator'],['autopilot','repeat','Money autopilot'],['smoothing','cash','Income smoothing'],['family','heart','Family support'],['family-space','users','Family spaces'],['health','shield','Stress radar'],['invisible','eye','Invisible spending'],['subscriptions','repeat','Subscriptions'],['cash','cash','Cash spending'],['voice','mic','Voice assistant'],['receipt','receipt','Receipt intelligence'],['memory','search','Money memory'],['life','goal','Life goals'],['emergency','shield','Emergency mode'],['bills','calendar','Bills & payments'],['invest','chart','Investments']];
function action(a){if(a==='close'){close();return;}if(a==='today'||a==='wallet'){navigate(a);return;}if(a==='intro-next'){if(state.step<3){state.step++;render();window.scrollTo(0,0);focusPage()}else navigate('today');return}if(a==='intro-back'){state.step=Math.max(0,state.step-1);render();window.scrollTo(0,0);focusPage();return}if(a==='onboarding'){state.step=0;navigate('intro');return}if(a==='reset'){modal('Reset this workspace?',`<p class="muted">This clears your session’s receipts, contributions, pots and settings, then restores the original sample finances.</p><button class="primary danger section" id="confirm-reset">Reset workspace</button><button class="primary secondary section" data-action="close">Keep my workspace</button>`);$('#confirm-reset').onclick=()=>{sessionStorage.removeItem('koloflow-payment-session');location.reload()};return}if(a==='tools'){modal('Money tools',`<div class="tool-grid">${toolsList.map(([v,i,t])=>`<button class="tool" data-action="${v}">${icon(i)}${t}</button>`).join('')}</div>`);return;}close();
if(a==='simulator'){modal('What if?',`<p class="muted">Explore a purchase or monthly commitment.</p><div class="form section"><label>Scenario<select id="scenario"><option value="purchase">Buy a laptop</option><option value="rent">Rent increases by 30%</option><option value="income">Lose expected client income</option><option value="saving">Save more each month</option></select></label><label>Amount (₦)<input id="sim-amount" type="number" min="0" max="100000000" value="1200000"></label></div><div class="summary" id="sim-result"></div><p class="disclosure">A sample projection for the next 30 days. This does not move money.</p>`);const calc=()=>{let n=Math.max(0,Number($('#sim-amount').value)||0),s=$('#scenario').value,c=s==='rent'?54000:s==='income'?240000:n;$('#sim-result').innerHTML=`Projected balance after 30 days<strong>${money(project(30)-c)}</strong>${project(30)-c<0?'This leaves a shortfall. Reduce the cost, delay the purchase, or revise your income plan.':`This leaves ${money(Math.max(0,safe()-c))} of today’s spending room.`}`};$('#scenario').onchange=()=>{const s=$('#scenario').value;$('#sim-amount').value={purchase:1200000,rent:54000,income:240000,saving:100000}[s];$('#sim-amount').disabled=['rent','income'].includes(s);calc()};$('#sim-amount').oninput=calc;calc();}
else if(a==='transfer'){transferForm();}
else if(a==='receive'){form('Receive money',field('source','Income source','Client payment')+field('amount','Amount (₦)','','number','min="1" max="10000000"'),d=>{completePayment({recipient:d.source,amount:Number(d.amount),kind:'Money received',method:'Naira account',incoming:true});},'Add sample income');}
else if(a==='card-pay'){cardPaymentForm();}
else if(a==='receipts'){receiptHistory();}
else if(a==='cash'){form('Log cash spending',field('purpose','What did you use it for?','Groceries')+field('amount','Cash spent (₦)','','number','min="1" max="1000000"'),d=>{const n=Number(d.amount);if(n>safe())return toast('This would exceed your safe spending room.');state.cash+=n;record('Cash: '+d.purpose,-n);close();render();toast('Cash expense recorded.')} ,'Record cash expense');}
else if(a==='new-pot'){form('Create money pot',field('name','Pot name')+field('target','Target (₦)','','number','min="1" max="100000000"'),d=>{state.pots.push({name:d.name,target:Number(d.target),amount:0,icon:'◈'});close();navigate('goals');toast('Your pot is ready.')} ,'Create pot');}
else if(a==='allocate'){modal('A little guidance',`<div class="summary">Based on ${money(safe())} of spending room, consider protecting:<strong>${money(safe()*.15)}</strong>15% for savings</div><p class="muted">Emergency fund: ${money(safe()*.10)}<br>Life goals: ${money(safe()*.05)}<br>Keep the remainder available for daily needs.</p><button class="primary section" data-action="autopilot">Set your own rules</button>`);}
else if(a==='autopilot'){modal('Money autopilot',`<p class="muted">Choose rules for future income in this prototype.</p><div class="section">${['Save 15% whenever money arrives','Put 5% into an emergency fund','Set aside ₦10,000 every Friday','Keep at least ₦50,000 untouched'].map((t,i)=>`<div class="list-row"><span>${t}</span><button class="toggle ${state.rules[i]?'on':''}" role="switch" aria-checked="${state.rules[i]}" aria-label="${t}" data-rule="${i}"><span></span></button></div>`).join('')}</div><p class="disclosure">Rules are demo preferences. They do not execute bank transfers.</p>`);}
else if(a==='smoothing'){form('Your own payday',field('reserve','Income reserve (₦)',600000,'number','min="1" max="100000000"')+field('salary','Monthly personal salary (₦)',200000,'number','min="1" max="10000000"'),d=>{let months=Number(d.reserve)/Number(d.salary);modal('Your salary plan',`<div class="summary">At ${money(Number(d.salary))} a month, your reserve lasts<strong>${months.toFixed(1)} months</strong></div><p class="muted">Keep this reserve separate from daily spending and review it whenever new income arrives.</p><p class="disclosure">Planning illustration only. No salary payments are scheduled.</p>`)} ,'Calculate runway');}
else if(a==='family'){form('Family support planner',`<div class="summary">Monthly budget: ₦50,000<br>Currently protected: ${money(state.family)}<br>Remaining room: ${money(Math.max(0,50000-state.family))}</div>`+field('amount','Set your total family reserve (₦)',state.family,'number','min="0" max="1000000"'),d=>{let n=Number(d.amount);if(n-state.family>safe())return toast('This reserve exceeds your current spending room.');state.family=n;close();render();toast(n>50000?'Reserve updated. You are above your family budget.':'Family reserve updated.')} ,'Update reserve');}
else if(a==='family-space'){modal('Family money space',`<h3>Our household</h3><div class="summary">Shared target<strong>₦120,000</strong>Josh: ${money(state.household)} · Amaka: ₦30,000<br>${money(Math.max(0,90000-state.household))} left to contribute</div><p class="muted">Members see this space’s contributions, without seeing each other’s personal balances.</p><button class="primary section" data-action="family-contribute" ${state.household>=90000?'disabled':''}>${state.household>=90000?'Shared goal complete':'Add a demo contribution'}</button>`);}
else if(a==='family-contribute'){const open=()=>form('Household contribution',field('amount','Contribution (₦)','','number',`min="1" max="${Math.max(1,90000-state.household)}"`),d=>reviewPayment({recipient:'Our household',amount:Number(d.amount),kind:'Household contribution',method:'Naira account',apply:()=>state.household+=Number(d.amount)},open),'Review contribution');open();}
else if(a==='health'||a==='alerts'){modal(a==='health'?'Financial stress radar':'Your notifications',`<div class="health"><span class="health-score">78</span><div><h3>Stable</h3><p class="muted">Sample financial health score</p></div></div><div class="stack section"><div class="summary">✓ ${state.paidBills.includes('rent')?'Your rent payment is complete.':'Your rent reserve covers the next payment.'}<br>✓ Expected income exceeds known bills.<br>! Dining is ₦18,000 over budget.<br>! Emergency savings cover only part of one month.</div></div><button class="primary" data-action="emergency">Explore emergency mode</button><p class="disclosure">The score is illustrative and is not a credit or lending score.</p>`);}
else if(a==='invisible'){modal('The little things add up',`<div class="summary">Delivery fees · Last 30 days<strong>₦71,400</strong>Small transfers under ₦5,000<strong>₦94,000</strong></div><p class="muted">Sample historical category totals. Some transactions may appear in both groups. Set a weekly cap to make these costs easier to notice.</p><button class="primary section" data-page="copilot">Talk it through with Kolo</button>`);}
else if(a==='subscriptions'){modal('Recurring payments',`<p class="muted">Estimated monthly total: <b>${money(state.subs.filter(s=>s.on).reduce((a,s)=>a+s.amount,0))}</b></p>${state.subs.map((s,i)=>`<div class="list-row"><div><h3>${s.name}</h3><p class="muted">${money(s.amount)} / month</p></div><button class="toggle ${s.on?'on':''}" role="switch" aria-checked="${s.on}" aria-label="Reserve for ${s.name}" data-sub="${i}"><span></span></button></div>`).join('')}<p class="disclosure">Switches change your demo reserves. Cancel subscriptions with each provider.</p>`);}
else if(a==='life'){form('Plan a life goal',`<label>Your next chapter<select name="goal"><option>Move house</option><option>Start a business</option><option>Get married</option><option>Travel</option><option>Buy a car</option><option>Go back to school</option><option>Have a baby</option></select></label>`+field('target','Estimated total cost (₦)',600000,'number','min="1" max="100000000"')+field('months','Months to prepare',12,'number','min="1" max="120"'),d=>{const n=Number(d.target)/Number(d.months);modal(d.goal+' · Your plan',`<div class="summary">Set aside each month<strong>${money(n)}</strong>For ${d.months} months · Total ${money(Number(d.target))}</div><p class="muted">${n>safe()?'This exceeds today’s free spending room. Consider extending the timeline.':'This fits within today’s spending room. Review it against future income before committing.'}</p><button class="primary section" id="create-life-pot">Create a goal pot</button>`);$('#create-life-pot').onclick=()=>{state.pots.push({name:d.goal,icon:'◈',target:Number(d.target),amount:0});close();navigate('goals');toast('Life goal pot created.')}} ,'Build my plan');}
else if(a==='new-circle'){form('Start an Ajo circle',field('name','Circle name')+field('amount','Monthly contribution (₦)',30000,'number','min="1" max="1000000"')+field('members','Number of members',6,'number','min="2" max="6"'),d=>{state.circles.push({name:d.name,amount:Number(d.amount),members:Number(d.members),received:0,paid:false,messages:[]});close();navigate('circles');toast('Demo circle created.')} ,'Create demo circle');}
else if(a==='history'){modal('Your activity',`<div class="stack">${state.transactions.map(tx).join('')}</div>`);}
else if(a==='memory'){modal('Money memory',`<label class="form">Search sample history<input id="memory-search" placeholder="Try landlord, Chisom or phone"></label><div id="memory-results" class="section"></div>`);const rows=[{name:'Landlord',amount:-180000,sub:'29 Sep 2026',icon:'home'},{name:'Chisom',amount:-15000,sub:'21 Sep 2026',icon:'users'},{name:'Phone purchase',amount:-145000,sub:'12 Aug 2026',icon:'cash'},...state.transactions];const filter=()=>{$('#memory-results').innerHTML=rows.filter(r=>r.name.toLowerCase().includes($('#memory-search').value.toLowerCase())).map(tx).join('')||`<p class="muted">No transactions match “${escape($('#memory-search').value)}”. Try a different name or clear your search.</p><button class="text-button" id="clear-memory">Clear search</button>`;bind($('#memory-results'));const clear=$('#clear-memory');if(clear)clear.onclick=()=>{$('#memory-search').value='';filter();$('#memory-search').focus()}};$('#memory-search').oninput=filter;filter();}
else if(a==='emergency'){form('Emergency mode',field('essential','Essential monthly expenses (₦)',115000,'number','min="1" max="10000000"'),d=>{const n=Number(d.essential);modal('Protect the essentials',`<div class="summary">Emergency runway<strong>${(state.balance/n).toFixed(1)} months</strong>Using ${money(state.balance)} available cash and ${money(n)} essential monthly costs.</div><p class="muted">1. Protect rent, food and healthcare.<br>2. Pause discretionary subscriptions.<br>3. Review optional savings rules.<br>4. Keep family support within a sustainable budget.</p><button class="primary section" data-action="subscriptions">Review what can be paused</button><p class="disclosure">This scenario uses all available cash and assumes no new income. Existing reserves may need to be reassigned.</p>`)} ,'Calculate survival plan');}
else if(a==='receipt'){modal('Receipt intelligence',`<p class="muted">Upload a receipt to preview it, or explore the sample extraction.</p><label class="form section">Receipt photo<input id="receipt-file" type="file" accept="image/*"></label><div id="receipt-preview"></div><button class="primary section" id="sample-receipt">Use sample receipt</button><p class="disclosure">Real receipt OCR is not connected in this prototype. Sample extraction is clearly marked.</p>`);$('#receipt-file').onchange=e=>{const f=e.target.files[0];if(!f)return;const u=URL.createObjectURL(f);$('#receipt-preview').innerHTML=`<img src="${u}" alt="Your receipt preview" style="width:100%;max-height:250px;object-fit:contain;margin-top:12px"><p class="disclosure">Preview only. Enter extracted details manually in Cash spending.</p>`};$('#sample-receipt').onclick=()=>{$('#receipt-preview').innerHTML='<div class="summary">Sample extraction<br>Merchant: Shoprite<br>Date: 5 October 2026<br>Groceries: rice, bread, milk<strong>₦12,450</strong>Category: Groceries</div>';};}
else if(a==='voice'){modal('Voice money assistant',`<p class="muted">Try “How much can I safely spend?” English and Pidgin examples are available below.</p><button class="primary section" id="start-voice">${icon('mic')}Start voice input</button><p id="voice-status" class="disclosure"></p><div class="stack section"><button class="prompt" data-prompt="How much can I safely spend?">How much can I safely spend?</button><button class="prompt" data-prompt="Kolo, how much I fit spend this weekend?">Kolo, how much I fit spend this weekend?</button></div>`);$('#start-voice').onclick=()=>{const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){$('#voice-status').textContent='Voice input is unavailable in this browser. Use a prompt above or type your question.';return}const r=new R();r.lang='en-NG';r.onresult=e=>{close();ask(e.results[0][0].transcript)};r.onerror=()=>{if($('#voice-status'))$('#voice-status').textContent='Microphone access did not complete. You can use the typed prompts.'};r.start();$('#voice-status').textContent='Listening…'};}
else if(a==='accounts'){modal('Your accounts',`<div class="list-row"><h3>Naira account · Sample</h3><b>${money(state.balance)}</b></div><div class="list-row"><h3>Dollar account · Sample</h3><b>$0.00</b></div><div class="list-row"><h3>Logged cash spending</h3><b>${money(state.cash)}</b></div><p class="disclosure">No bank accounts are connected.</p>`);}
else if(a==='invest'){form('Investment planner',field('amount','Monthly investment (₦)',10000,'number','min="1" max="10000000"')+field('months','Number of months',12,'number','min="1" max="120"'),d=>modal('Your contributions',`<div class="summary">Total invested before any returns<strong>${money(Number(d.amount)*Number(d.months))}</strong></div><p class="muted">This model assumes no return. Investment values can rise or fall.</p>`),'Calculate contributions');}
else if(a==='bills'){modal('Upcoming commitments',`<p class="muted">Review a bill before you pay. Reserved money covers these commitments.</p>${[['rent','Rent',180000,'29 October'],['recurring','Recurring payments',state.subs.filter(s=>s.on).reduce((n,s)=>n+s.amount,0),'12 October']].map(([id,name,n,date])=>`<div class="bill-payment"><div><h3>${name}</h3><p class="muted">${date} · ${money(n)}</p></div><button class="${state.paidBills.includes(id)?'badge':'primary'}" data-pay-bill="${id}" ${state.paidBills.includes(id)||!n?'disabled':''}>${state.paidBills.includes(id)?'Paid':'Pay now'}</button></div>`).join('')}<div class="list-row"><h3>Family reserve</h3><b>${money(state.family)}</b></div><button class="text-button" data-action="receipts">Payment receipts</button><button class="primary secondary section" data-action="subscriptions">Manage recurring reserves</button>`);}
else if(a==='card-block'){state.frozen=!state.frozen;render();toast(state.frozen?'Demo card frozen.':'Demo card unfrozen.');}
else if(a==='card-details'){modal('Demo card details',`<div class="summary">Cardholder: Josh Ehiz<br>Ending: 4327<br>Status: ${state.frozen?'Frozen':'Active'}<br>Spending limit: ${money(safe())}</div><p class="disclosure">This is a display card. It has no payment network connection.</p>`);}}
function bind(root=document){root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{close();navigate(b.dataset.page)});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;render()});root.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{close();ask(b.dataset.prompt)});root.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>{const i=+b.dataset.rule;state.rules[i]=!state.rules[i];b.classList.toggle('on',state.rules[i]);b.setAttribute('aria-checked',state.rules[i]);persistState();toast('Demo rule updated.')});root.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{state.subs[+b.dataset.sub].on=!state.subs[+b.dataset.sub].on;render();action('subscriptions')});root.querySelectorAll('[data-pot]').forEach(b=>b.onclick=()=>{const p=state.pots[+b.dataset.pot];form('Add to '+p.name,field('amount','Amount to protect (₦)','','number','min="1" max="10000000"'),d=>{const n=Number(d.amount);if(n>safe())return toast('That exceeds your safe spending room.');p.amount+=n;close();render();toast('Money protected in your pot.')},'Protect this amount')});root.querySelectorAll('[data-circle-pay]').forEach(b=>b.onclick=()=>{const c=state.circles[+b.dataset.circlePay];if(c.paid)return;reviewPayment({recipient:c.name,amount:c.amount,kind:'Circle contribution',method:'Naira account',apply:()=>c.paid=true},()=>{close();navigate('circles')});});root.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>showReceipt(state.receipts.find(r=>r.id===b.dataset.receipt)));root.querySelectorAll('[data-pay-bill]').forEach(b=>b.onclick=()=>{const id=b.dataset.payBill;if(state.paidBills.includes(id))return;const n=id==='rent'?180000:state.subs.filter(s=>s.on).reduce((a,s)=>a+s.amount,0);reviewPayment({recipient:id==='rent'?'Landlord':'Recurring providers',amount:n,kind:'Bill payment',method:'Naira account',release:n,apply:()=>state.paidBills.push(id)},()=>action('bills'));});root.querySelectorAll('[data-circle-detail]').forEach(b=>b.onclick=()=>circleDetail(+b.dataset.circleDetail));const f=root.querySelector('#future-day');if(f)f.oninput=()=>{state.day=Number(f.value);persistState();$('#forecast-amount').textContent=money(project(state.day));$('#day-label').textContent='Day '+state.day;$('#chart-point').setAttribute('cx',8+state.day/30*322);$('#chart-point').setAttribute('cy',chartY(project(state.day)))};const chat=root.querySelector('#chat-form');if(chat)chat.onsubmit=e=>{e.preventDefault();const q=$('#chat-input').value.trim();if(q)ask(q)};}
function circleDetail(i){const c=state.circles[i];modal(c.name,`<div class="tabs" style="border-color:#dde4d8"><button class="active" data-circle-tab="ledger">Ledger</button><button data-circle-tab="order">Payouts</button><button data-circle-tab="chat">Chat</button><button data-circle-tab="vote">Vote</button></div><div id="circle-view"></div><p class="disclosure">Sample group data · Reliability builds as contributions are recorded.</p>`);const view=t=>{$('#circle-view').innerHTML=t==='ledger'?['Josh','Amaka','Chisom','Tolu','Kehinde','Emeka'].slice(0,c.members).map((n,j)=>`<div class="list-row"><span>${n}</span><span class="badge">${(j===0?c.paid:j<=(c.received??c.members-1))?'Paid '+money(c.amount):'Pending'}</span></div>`).join(''):t==='order'?['Amaka · 10 Oct','Josh · 10 Nov','Chisom · 10 Dec','Tolu · 10 Jan','Kehinde · 10 Feb','Emeka · 10 Mar'].slice(0,c.members).map((n,j)=>`<div class="list-row"><span>${j+1}. ${n}</span><b>${money(c.amount*c.members)}</b></div>`).join(''):t==='chat'?'<div id="group-messages" class="stack"><div class="message">Amaka: A little reminder — contributions are due on the 10th.</div>'+ (c.messages||[]).map(m=>'<div class="message user">You: '+escape(m)+'</div>').join('') +'</div><form id="group-chat" class="compose"><input id="group-input" placeholder="Message your circle" required maxlength="200" aria-label="Group message"><button class="round" aria-label="Send group message">'+icon('send')+'</button></form>':'<div class="summary">Emergency request: bring Tolu’s payout forward.<br>Current sample votes: 3 support · 1 decline · 2 pending'+(c.vote?'<br>Your vote: '+escape(c.vote):'')+'</div><button class="primary" id="vote-yes">Support request</button><button class="primary secondary section" id="vote-no">Keep current order</button>';if(t==='chat')$('#group-chat').onsubmit=e=>{e.preventDefault();const v=$('#group-input').value.trim();if(v){(c.messages??=[]).push(v);persistState();$('#group-messages').insertAdjacentHTML('beforeend',`<div class="message user">You: ${escape(v)}</div>`);$('#group-input').value=''}};if(t==='vote')for(const [id,label] of [['vote-yes','Support'],['vote-no','Decline']])$('#'+id).onclick=()=>{c.vote=label;persistState();$('#circle-view').innerHTML=`<div class="summary">Your demo vote was recorded: ${label}.<br>The group payout order has not changed.</div>`;};};$('#modal').querySelectorAll('[data-circle-tab]').forEach(b=>b.onclick=()=>{$('#modal').querySelectorAll('[data-circle-tab]').forEach(x=>x.classList.toggle('active',x===b));view(b.dataset.circleTab)});view('ledger');}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close()});render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'navigate_money_view',description:'Open a KoloFlow money view in this portfolio prototype.',inputSchema:{type:'object',properties:{view:{type:'string',enum:pages.map(p=>p[0])}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({view})=>{if(!pages.some(p=>p[0]===view))throw new Error('Unknown money view');navigate(view);return{view,balance:state.balance,safeToSpend:safe()}}});}catch{}}
